      "fullUrl": "https://example.org/fhir/Observation/observation-18",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-18",
        "status": "final",
        "code": {
          "text": "Alcohol intake"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports 4–8 standard drinks per week, sometimes more after a bad day."
